document.addEventListener("click",a=>{const c=a.target.closest("a.entry-image");if(!c)return;a.preventDefault();const d=c.href,e=document.createElement("div");e.className="modal-backdrop",e.innerHTML=`<div class="modal"><div class="modal-head"><h2>Image Preview</h2><button class="icon-btn" data-close>✕</button></div><div style="padding:16px;text-align:center"><img src="${d}" style="max-width:100%;height:auto;max-height:80vh"></div></div>`,document.body.append(e),e.querySelectorAll("[data-close]").forEach(t=>t.onclick=()=>e.remove()),e.addEventListener("click",t=>{t.target===e&&e.remove()})});
